def parse_duration(s):
    if not s:
        return None
    s = s.lower()
    if 'h' in s:
        h, m = s.split('h')
        m = m.strip('m')
        return int(h) * 3600 + int(m) if m else int(h) * 3600
    if 'm' in s:
        m, s = s.split('m')
        return int(m) * 60 + int(s.strip('s')) if s else int(m) * 60
    if 's' in s:
        return int(s.strip('s'))
    return None
