def split_top_level(s):
    stack, result, current = [], [], ""
    for char in s + ",":  # 加上一个逗号确保最后一个元素也能处理
        if char in "([{":
            if stack:
                current += char
            stack.append(char)
        elif char in ")]}":
            stack.pop()
            current += char
            if not stack:
                trimmed = current.strip()
                if trimmed:
                    result.append(trimmed)
                current = ""
        elif char == "," and not stack:
            trimmed = current.strip()
            if trimmed:
                result.append(trimmed)
            current = ""
        else:
            current += char
    return result
```

