def flatten_nested(d):
    def _flatten(item, parent_key=''):
        for k, v in item.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                yield from _flatten(v, new_key)
            elif v is not None and isinstance(v, list):
                for i, val in enumerate(v):
                    yield (f"{new_key}[{i}]", val)
            elif v is not None:
                yield (new_key, v)

    return dict(_flatten(d))
