def gcd_lcm(a, b):
    a, b = abs(a), abs(b)
    if a == 0 and b == 0:
        return (0, 0)
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x
    gcd_val = gcd(a, b)
    lcm_val = a * b // gcd_val
    return (gcd_val, lcm_val)
