def median(seq):
    if not seq:
        return None
    seq_sorted = sorted(seq)
    n = len(seq_sorted)
    if n % 2 == 1:
        return seq_sorted[n // 2]
    else:
        return (seq_sorted[n // 2 - 1] + seq_sorted[n // 2]) / 2
