class TxError(Exception):
    pass

class Tx:
    def __init__(self):
        self.staged = {}  # 暂存区
        self.active = False  # 是否有活跃事务
        self.persistence = {}  # 持久状态

    def begin(self):
        if self.active:
            raise TxError("Already in an active transaction")
        self.active = True

    def put(self, k, v):
        if not self.active:
            raise TxError("No active transaction")
        self.staged[k] = v

    def delete(self, k):
        if not self.active:
            raise TxError("No active transaction")
        self.staged[k] = None

    def get(self, k):
        if not self.active:
            return self.persistence.get(k)
        return self.persistence.get(k) if k not in self.staged else self.staged[k]

    def scan(self):
        if not self.active:
            return sorted([k for k, v in self.persistence.items() if v is not None])
        return sorted([k for k, v in {**self.persistence, **self.staged}.items() if v is not None])

    def commit(self):
        if not self.active:
            raise TxError("No active transaction")
        self.persistence.update(self.staged)
        self.staged = {}
        self.active = False

    def rollback(self):
        if not self.active:
            raise TxError("No active transaction")
        self.staged = {}
        self.active = False
