class LRU:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.keys = []

    def get(self, k):
        if k in self.cache:
            self.keys.remove(k)
            self.keys.append(k)
            return self.cache[k]
        return None

    def put(self, k, v):
        if k in self.cache:
            self.keys.remove(k)
        elif len(self.cache) >= self.capacity:
            del self.cache[self.keys[0]]
            del self.keys[0]
        self.cache[k] = v
        self.keys.append(k)

    def keys(self):
        return self.keys[::-1]

