from lru import LRU

class Tiered:
    def __init__(self, l1_capacity):
        self.l1 = LRU(l1_capacity)
        self.l2 = {}

    def put(self, k, v):
        if k in self.l1.cache:
            self.l1.cache[k] = v
            self.l1.keys.remove(k)
            self.l1.keys.append(k)
        else:
            self.l1.put(k, v)
            self.l2[k] = v

    def get(self, k):
        if k in self.l1.cache:
            self.l1.cache[k] = self.l1.cache[k]
            self.l1.keys.remove(k)
            self.l1.keys.append(k)
            return k
        elif k in self.l2:
            self.l1.put(k, self.l2[k])
            return k
        return None
